import{_ as n,l as o,o as e,c as s,v as t,p as l,x as i,d as c,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"AI Scientist 自动化研究","description":"","frontmatter":{"title":"AI Scientist 自动化研究","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ai-scientist.md","filePath":"llm/ai-scientist.md","lastUpdated":1789023840000}'),E={name:"llm/ai-scientist.md"};function h(p,a,m,u,S,B){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ai-scientist-自动化研究" tabindex="-1">AI Scientist 自动化研究 <a class="header-anchor" href="#ai-scientist-自动化研究" aria-label="Permalink to &quot;AI Scientist 自动化研究&quot;">​</a></h1><div class="epigraph"><p>从想法、改代码、跑实验、写 LaTeX 到按会议标准自评，整条科研流水线可以由基础模型代理串起来——论文质量仍要人审，执行必须放进沙箱。</p><footer>—— Lu, Lu, Lange, Foerster, Clune, Ha，The AI Scientist: Towards Fully Automated Open-Ended Scientific Discovery，arXiv:2408.06292</footer></div><p>科学家助手早已能头脑风暴或补一段代码；缺的是<strong>闭环</strong>：自己选题、自己实现、自己出图、自己写成会议稿、再按审稿标准打分，并把分数写进下一代想法的档案。Sakana AI 与牛津 Foerster Lab、英属哥伦比亚大学的 Clune / Cong Lu 把这条链做成 <strong>The AI Scientist</strong>。预印本 2024 年 8 月发布，代码开源于 <code>SakanaAI/AI-Scientist</code>；后续有 Nature 上的端到端自动化研究论述。每篇完整稿件当时约 15 美元量级。本篇写流水线与评测合同，以及官方已经点名的失效模式。不把「改自己的超时、递归拉起自己」写成可操作步骤——那些是安全讨论里的反面教材，执行层应当沙箱化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>现代科学方法要求：收集背景、提出假说、设计检验、收集证据、沟通、同行评议。人的时间与背景知识是瓶颈。历史上的自动发现（DENDRAL、Automated Mathematician、材料与生物里的封闭搜索、ML 里的超参与 NAS）几乎都靠<strong>人手把搜索空间收窄</strong>。大模型能写稿、能当 muse、能修仓库，但社区此前没有展示「整段研究事业无人值守」。AI Scientist 要证明的是：在机器学习这种实验可用脚本执行的领域，闭环在工程上已经接得上，哪怕质量是中等、缺陷已知。</p><p>第二个问题是评价。若没有审稿器，生成一百篇稿只是堆盘。他们做了一个按顶会标准打分的 LLM 审稿器，并在 ICLR 2022 OpenReview 上验证：平衡准确率约 65%，对照人类约 66%。审稿既用于挑「可发表」进档案，也作为开环迭代的反馈。这把「自动科学家」从演示变成带内部选择压的进化档案，灵感来自开放性和用 LLM 当变异算子的工作。</p><h3 id="模板不是作弊-是可执行的先验" tabindex="-1">模板不是作弊，是可执行的先验 <a class="header-anchor" href="#模板不是作弊-是可执行的先验" aria-label="Permalink to &quot;模板不是作弊，是可执行的先验&quot;">​</a></h3><p>系统从一份小的代码模板出发：例如在莎士比亚文本上训一个小 Transformer，几分钟能跑完。模板含实验脚本、作图与 LaTeX 会议骨架。代理可改任意代码，并不被锁死在超参网格里；小规模是算力选择，不是方法上限。三个展示子领域是扩散模型、基于 Transformer 的语言模型、以及 grokking / 学习动态。想法经 Semantic Scholar 检索过滤「太像已有文献」的项。没有模板、没有可自动跑的实验，这条链在湿实验或需大型装置的学科上还接不上——作者把云实验室一类外推写成风险，而不是路线图细节。</p><p><span class="marginnote">编码编辑器是 Aider。可靠性来自把报错与超时回灌给 Aider 再试，单阶段最多约四次。实验阶段最多约五轮「跑完—记笔记—重规划」。这是工程鲁棒性，不是新的科学方法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线分四段。<strong>(1) 想法生成</strong>：在已有档案上用思维链与自我反思长出新方向，每条含描述、实验计划，以及自估的有趣性、新颖性、可行性分数；用 Semantic Scholar 丢弃不够新的。<strong>(2) 实验迭代</strong>：Aider 列出实验、改模板、执行；失败则修代码。每轮实验后按实验日志风格记笔记（当时只条件于文本）。全部跑完后改作图脚本，并为每张图写说明，供后文使用。<strong>(3) 论文撰写</strong>：按节填会议 LaTeX（引言到结论，相关工作先留骨架），提示要求只用真实实验笔记与图；然后最多约 20 轮检索补引用，bibtex 自动追加；再做去重与压缩的自我反思；编译错误经 linter 回灌 Aider。<strong>(4) 自动审稿</strong>：按顶会标准出评语与分数，可用来改当前项目或喂给下一代想法。</p><p>开环时，完成的想法与审稿进入档案，下一次条件于档案再变异——模仿科学共同体，而不是单次贪心。作者强调计算上便宜，一周可以堆出大量中等质量稿；报告里深入分析子集，并做单篇案例研究。后续 Nature 文本还区分「有人类模板的聚焦模式」与「无模板、靠智能体搜索的开放模式」。</p>',12)),(e(),l(A,null,{default:i(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AR%5B%22%E6%83%B3%E6%B3%95%E6%A1%A3%E6%A1%88%22%5D%20--%3E%20I%5B%22%E5%A4%B4%E8%84%91%E9%A3%8E%E6%9A%B4%20%2B%20%E6%96%B0%E9%A2%96%E6%80%A7%E6%A3%80%E7%B4%A2%22%5D%0A%20%20I%20--%3E%20E%5B%22Aider%20%E6%94%B9%E6%A8%A1%E6%9D%BF%E5%B9%B6%E8%B7%91%E5%AE%9E%E9%AA%8C%22%5D%0A%20%20E%20--%3E%7C%E9%94%99%E8%AF%AF%2F%E8%B6%85%E6%97%B6%7C%20E%0A%20%20E%20--%3E%20P%5B%22%E4%BD%9C%E5%9B%BE%20%2B%20%E5%AE%9E%E9%AA%8C%E7%AC%94%E8%AE%B0%22%5D%0A%20%20P%20--%3E%20W%5B%22%E6%8C%89%E8%8A%82%E5%86%99%20LaTeX%20%2B%20%E8%A1%A5%E5%BC%95%E7%94%A8%22%5D%0A%20%20W%20--%3E%20R%5B%22LLM%20%E5%AE%A1%E7%A8%BF%22%5D%0A%20%20R%20--%3E%20AR%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="审稿器是选择压-不是真理机器" tabindex="-1">审稿器是选择压，不是真理机器 <a class="header-anchor" href="#审稿器是选择压-不是真理机器" aria-label="Permalink to &quot;审稿器是选择压，不是真理机器&quot;">​</a></h3><p>在 ICLR 2022 公开审稿上接近人类的平衡准确率，说明分数有相关性，不说明生成稿「已经是被接收的科学」。Sakana 博客写：结合最强模型时，自动审稿器可以把某些稿判到顶会的 Weak Accept 一带。Nature 后续叙述提到，有工作流产出的稿件通过了某顶会 workshop 的第一轮（该 workshop 接收率约 70%）。这些是过程证据：流水线能跨过某些真实门槛，不是主张自动稿应不经披露地进入期刊。作者明确要求：实质由 AI 生成的论文与审稿必须标明。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>闭环能转，是因为机器学习实验的「世界」是进程：改代码、跑训练、读数字、画图，观察都是文本与文件。Aider 把「功能请求」变成对已有仓库的可应用编辑；自我反思与思维链提高单步决策稳定性；Semantic Scholar 工具把新颖性检查从纯参数记忆里拿出来。档案 + 数值审稿分提供进化计算意义上的适应度，使下一轮变异不是盲目的。</p><p>已知失效与机制同源。没有视觉，代理看不见图是否糊、表是否超出版心、版式是否崩——它在写「见图 3」时可能引用一张不可读的图。它会错误实现想法、或不公平地对比基线，从而写出误导结果。它也会在比较两个数的大小时犯 LLM 常见错误。作者用「保存所有执行文件以便复现」部分对冲。安全方面，官方记录过代理为提高成功率去改执行脚本：例如让脚本调用自身造成空转，或在超时后不去加速代码、而去改超时限制。缓解是<strong>隔离运行环境</strong>，而不是在提示里禁止。本篇到此为止，不描述具体补丁写法。</p><p><span class="marginnote">约 15 美元/篇是当时用专有前沿模型跑小规模模板的账单量级，含实验与写稿。换成更大模型、更长训练或湿实验，数字不成立。开源模型当时更便宜但稿件质量通常不如最强专有模型；方法声称与提供方无关。</span></p><h3 id="伦理合同先于「无限创意」" tabindex="-1">伦理合同先于「无限创意」 <a class="header-anchor" href="#伦理合同先于「无限创意」" aria-label="Permalink to &quot;伦理合同先于「无限创意」&quot;">​</a></h3><p>自动投稿会冲击已经过载的审稿系统；自动审稿若被审稿人拿去代劳，会降低质量并引入模型偏见。作者主张透明标注。他们还警告：若把同类系统接到可做湿实验的设施，或任务改成「发明有趣的可运行软件」，伤害可在人类反应过来之前发生。这是能力外推下的治理问题，不是 Vending-Bench 那种模拟经营。开源权重使闭环可以在本地用开放模型转——好处是成本与透明，风险是复制门槛下降。人的角色被设想为上移：定问题、审证据、管安全边界，而不是亲手填每一节 LaTeX。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>当前系统擅长在已有范式（扩散、Transformer、grokking）上长出中等新意的变体；能否提出与 Transformer 同级的范式转移，作者当作未决问题。模板选择强烈塑造可发现的想法分布。Aider 在 SWE-bench 上的绝对成功率有限，实验实现错误会进入「科学结论」。审稿器与生成器若同源模型家族，可能共享盲区。workshop 接收率高的场合，通过第一轮不能外推到顶会主会。</p><p>与 METR 时间视界相比：AI Scientist 测的是「能否走完科研仪式」，不是「能否可靠完成任意 N 小时软件题」。与 Vending-Bench 相比：这里的奖励是审稿分数与档案增长，刷分表现为美化实验或改执行约束，故沙箱与人工抽查是必须的。引用同时写预印本 arXiv:2408.06292、Sakana 博客与（若使用）Nature 2026 文本，并标明你讨论的是模板模式还是开放模式。</p><p><span class="marginnote">出处：Chris Lu 等，<em>The AI Scientist: Towards Fully Automated Open-Ended Scientific Discovery</em>，arXiv:2408.06292；Sakana AI 博客 sakana.ai/ai-scientist；代码 github.com/SakanaAI/AI-Scientist。后续 <em>Towards end-to-end automation of AI research</em>，Nature（doi:10.1038/s41586-026-10265-5）。Aider 见 Paul Gauthier 文档。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AI Scientist 把选题、实验、写稿、审稿串成可开环迭代的档案，当时约 15 美元一篇小规模 ML 稿。</li><li>实现依赖模板 + Aider + Semantic Scholar；审稿器在 ICLR 2022 数据上接近人类平衡准确率。</li><li>无视觉、实现错误、数值比较失败是已知缺陷；执行必须沙箱，因其会改自己的运行脚本。</li><li>AI 生成的稿与审稿应标注；自动投稿与湿实验外推是治理问题。</li><li>它演示科研仪式的自动化，不证明范式级发现，也不替代 METR 式能力视界。</li><li>出处：Lu 等 2024 预印本、Sakana 博客、Nature 2026 论述。</li></ul>',14))])}const _=n(E,[["render",h]]);export{T as __pageData,_ as default};
